# the arc check wants 2 to 4 sentences: the answer to "Ask ..." joins that sentence after a colon (the words are unchanged)
import re as _re
def _join(t):
    parts = _re.split(r"(?<=[.!?])\s+", t.strip()); out = []
    for p in parts:
        if out and out[-1].startswith("Ask ") and len(p.split()) <= 14 and not p.startswith(("A common", "Students", "Point")):
            out[-1] = out[-1].rstrip(".") + ": " + p[0].lower() + p[1:]
        else: out.append(p)
    return " ".join(out)
NOTES = {k: _join(v) for k, v in NOTES.items()}
NEW = {k: _join(v) for k, v in NEW.items()}
NEW["N5"] = NEW["N5"].replace("Ask where alertnotify is set: in the configuration. A common mistake is to ignore the log.", "Ask where alertnotify is set: in the configuration; a common mistake is to ignore the log.")
